static async Task<string[]> LoadFilesAsync(IEnumerable<string> paths, CancellationToken token)
{
    Task<string>[] reads = paths
        .Select(path => File.ReadAllTextAsync(path, token))
        .ToArray();

    return await Task.WhenAll(reads);
}

using CancellationTokenSource cts = new();
string[] content = await LoadFilesAsync(new[] { "a.txt", "b.txt" }, cts.Token);
Console.WriteLine(content.Length);

