public record Assessment(string Module, int Score);

static string Classify(Assessment assessment) => assessment switch
{
    { Score: >= 90 } => "Excellent",
    { Score: >= 80 } => "Pass",
    { Score: >= 0 } => "Retry",
    _ => throw new ArgumentOutOfRangeException(nameof(assessment))
};

Assessment result = new("C#", 92);
Assessment revised = result with { Score = 95 };
Console.WriteLine(Classify(revised));

